function photoUrl(path){if(!path)return '';if(path.startsWith('https://'))return path;if(!ready)return '';return db.storage.from('website-motorcycle-photos').getPublicUrl(path).data.publicUrl}
function preloadBikePhotos(){
 const list=bikes.filter(b=>b.available).flatMap(b=>(b.photos||[]).slice(1)).concat(bikes.filter(b=>!b.available).flatMap(b=>(b.photos||[]).slice(1)));
 let index=0,active=0;const max=3;
 const run=()=>{while(active<max&&index<list.length){const path=list[index++],url=photoUrl(path);if(!url||preloadedPhotos.has(url))continue;const img=new Image();preloadedPhotos.set(url,img);active++;img.onload=img.onerror=()=>{active--;run()};img.src=url;}};
 if('requestIdleCallback' in window)requestIdleCallback(run,{timeout:1600});else setTimeout(run,300);
}
