const fields=[['full_name','Nome completo','text'],['cpf','CPF','text'],['birth_date','Data de nascimento','text'],['phone','Telefone com DDD','tel'],['email','E-mail','email'],['address','Endereço','text'],['house_number','Número da casa','text'],['neighborhood','Bairro','text'],['relative_1_name','Nome do parente','text'],['relative_1_phone','Telefone com DDD','tel'],['relative_1_relation','Grau de parentesco','select'],['relative_2_name','Nome do parente','text'],['relative_2_phone','Telefone com DDD','tel'],['relative_2_relation','Grau de parentesco','select']];
