function formGallery(b){const photos=galleryPhotos(b);if(!photos.length)return '';return `<div class="form-gallery ${photos.length===1?'single-photo':''}" id="form-gallery"><button type="button" class="gallery-arrow" id="gallery-prev" aria-label="Foto anterior">‹</button><div class="gallery-photo"><img id="gallery-img" src="${esc(photoUrl(photos[0]))}" alt="Foto da moto ${esc(b.model)}"></div><button type="button" class="gallery-arrow" id="gallery-next" aria-label="Próxima foto">›</button></div><div class="gallery-indicators" id="gallery-indicators">${photos.map((_,i)=>`<span class="${i===0?'active':''}"></span>`).join('')}</div>`}
function bindFormGallery(b){const photos=galleryPhotos(b),img=$('#gallery-img');if(!img)return;let current=0;const move=delta=>{current=(current+delta+photos.length)%photos.length;img.src=photoUrl(photos[current]);document.querySelectorAll('#gallery-indicators span').forEach((el,i)=>el.classList.toggle('active',i===current))};$('#gallery-prev').onclick=()=>move(-1);$('#gallery-next').onclick=()=>move(1);if(photos.length<2){$('#gallery-prev').classList.add('hidden');$('#gallery-next').classList.add('hidden')}}
const relations=['Pai','Mãe','Irmão','Irmã','Avô','Avó','Tio','Tia','Filho','Filha','Primo','Prima','Cunhado','Cunhada','Sogro','Sogra','Genro','Nora'];
function fieldHtml(id,label,type,values){if(type==='select')return `<div class="field"><label for="${id}">${label} *</label><select id="${id}" name="${id}" required><option value="">Selecione o parentesco</option>${relations.map(r=>`<option value="${r}" ${values[id]===r?'selected':''}>${r}</option>`).join('')}</select><span class="error" data-error="${id}"></span></div>`;
return `<div class="field"><label for="${id}">${label} *</label><input id="${id}" name="${id}" type="${type}" value="${esc(values[id]||'')}" ${id==='cpf'?'inputmode="numeric" maxlength="14"':id==='birth_date'?'inputmode="numeric" maxlength="10" placeholder="DD/MM/AAAA"':id.includes('phone')?'inputmode="tel"':''} required><span class="error" data-error="${id}"></span></div>`}
function showForm(values={}){modal(`${formGallery(selectedBike)}<h2 class="form-bike-title">SOLICITAR ALUGUEL ${esc(selectedBike.model.replace(/^Honda\s+/i,''))} ${esc(selectedBike.year)}</h2><form id="application-form" novalidate>${fields.slice(0,8).map(([id,label,type])=>fieldHtml(id,label,type,values)).join('')}<section class="relatives-section"><h3>👥 CONTATO DE DOIS PARENTES PRÓXIMOS</h3><div class="relatives-grid">${[1,2].map(n=>`<div class="relative-card"><h4>${n}º PARENTE</h4>${fields.slice(8+(n-1)*3,11+(n-1)*3).map(([id,label,type])=>fieldHtml(id,label,type,values)).join('')}</div>`).join('')}</div></section><div class="field"><label>CNH DIGITAL EM PDF *</label><div class="file-control"><input type="file" id="cnh" accept="application/pdf,.pdf" required><span id="cnh-ok" class="upload-ok hidden">✓</span></div><span class="error" data-error="cnh"></span><p id="cnh-preparation-note" class="muted">Ao escolher o PDF, iniciaremos a conferência da CNH para agilizar o envio.</p></div><div class="field"><label>Foto do rosto *</label><div class="file-control"><input type="file" id="face" accept="image/jpeg,image/png" required><img id="face-preview" class="face-thumb hidden" alt="Miniatura da foto"><span id="face-ok" class="upload-ok hidden">✓</span></div><button type="button" class="mini" id="take-face">Tirar foto pela câmera</button><input type="file" id="camera-face" accept="image/*" capture="user" class="hidden"><span class="error" data-error="face"></span></div><div class="actions"><button id="submit-application" type="submit" class="btn primary submit-green">ENVIAR CADASTRO</button></div></form>`);
document.getElementById('modal').classList.add('form-fullscreen');bindFormGallery(selectedBike);const form=$('#application-form');form.addEventListener('input',()=>{rememberForm();scheduleCnhPreparation();});form.addEventListener('change',()=>{rememberForm();scheduleCnhPreparation();});fields.forEach(([id])=>form.elements[id].addEventListener('blur',()=>{validate(id);if(id.includes('phone'))checkContactFields().catch(()=>toast('Não foi possível conferir os contatos. Tente novamente.'))}));const birthInput=$('#birth_date');birthInput.addEventListener('input',()=>{let s=birthInput.value.replace(/\D/g,'').slice(0,8);birthInput.value=s.length>4?s.slice(0,2)+'/'+s.slice(2,4)+'/'+s.slice(4):s.length>2?s.slice(0,2)+'/'+s.slice(2):s;});['cnh','face'].forEach(id=>$('#'+id).onchange=()=>{validate(id);$('#'+id+'-ok').classList.toggle('hidden',!($('#'+id).files[0]&&validate(id)));if(id==='face'&&$('#face').files[0]){const url=URL.createObjectURL($('#face').files[0]);$('#face-preview').src=url;$('#face-preview').classList.remove('hidden')}});const prior=formDrafts.get(String(selectedBike.id));if(prior){for(const id of ['cnh','face']){if(prior[id]){const dt=new DataTransfer();dt.items.add(prior[id]);document.getElementById(id).files=dt.files;document.getElementById(id).dispatchEvent(new Event('change'));}}}$('#take-face').onclick=()=>$('#camera-face').click();$('#camera-face').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const img=await createImageBitmap(f),canvas=document.createElement('canvas');const scale=Math.min(1,1800/Math.max(img.width,img.height));canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',0.9)),dt=new DataTransfer();dt.items.add(new File([blob],'foto.jpg',{type:'image/jpeg'}));$('#face').files=dt.files;$('#face').onchange()}catch{toast('Não foi possível usar esta foto. Escolha JPG ou PNG na galeria.')}};form.onsubmit=submitApplication;scheduleCnhPreparation();}
function validCpf(s){s=s.replace(/\D/g,'');if(s.length!==11||/^(\d)\1{10}$/.test(s))return false;for(let n=9;n<=10;n++){let sum=0;for(let i=0;i<n;i++)sum+=Number(s[i])*(n+1-i);if(((sum*10)%11)%10!==Number(s[n]))return false}return true}
function validate(id){let el=$('#'+id),v=el.type==='file'?el.files[0]:el.value.trim(),err='';if(id==='full_name'&&v.split(/\s+/).filter(Boolean).length<2)err='Informe seu nome completo.';if(id==='cpf'&&!validCpf(v))err='CPF inválido. Confira os números digitados.';if((id==='phone'||/^relative_[12]_phone$/.test(id))&&!/^\d{10,11}$/.test(v.replace(/\D/g,'').replace(/^55(?=\d{10,11}$)/,'')))err='Informe um telefone com DDD válido.';if(id==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))err='Informe um e-mail válido.';if(id==='neighborhood'&&(v.length<2||v.length>100))err='Informe o bairro (de 2 a 100 caracteres).';if(id==='address'&&(v.length<3||v.length>200))err='Informe o endereço (até 200 caracteres).';if(id==='house_number'&&(v.length<1||v.length>20))err='Informe o número da casa (ou S/N).';if(/^relative_[12]_name$/.test(id)&&v.length<2)err='Informe o nome do parente.';if(/^relative_[12]_relation$/.test(id)&&!relations.includes(v))err='Selecione o parentesco.';if(id==='birth_date'){let parts=v.split('/'),iso=parts.length===3?parts[2]+'-'+parts[1]+'-'+parts[0]:v,birth=new Date(iso+'T12:00:00'),today=new Date(),age=today.getFullYear()-birth.getFullYear()-(today.getMonth()<birth.getMonth()||(today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate())?1:0);if(!v||Number.isNaN(birth.getTime())||birth.getDate()!==Number(parts[0])||birth.getMonth()+1!==Number(parts[1])||birth.getFullYear()!==Number(parts[2])||v.length!==10||age<18||age>120)err='É necessário ter pelo menos 18 anos.'}if(id==='cnh'||id==='face'){if(!v||v.size===0)err='Selecione um arquivo obrigatório.';else if(v.size>5*1024*1024)err='O arquivo deve ter no máximo 5 MB.';else if(id==='cnh'&&!(v.type==='application/pdf'&&v.name.toLowerCase().endsWith('.pdf')))err='Envie um PDF válido.';else if(id==='face'&&!['image/jpeg','image/png'].includes(v.type))err='Envie uma foto JPG ou PNG.'}const msg=document.querySelector(`[data-error="${id}"]`);if(msg)msg.textContent=err;return !err}
async function checkContactFields(){
 const form=document.getElementById('application-form');if(!form)return true;
 const {checkContacts}=await import('./validation.js');
 const data=Object.fromEntries(['phone','relative_1_phone','relative_2_phone'].map(id=>[id,form.elements[id].value]));
 for(const id of ['relative_1_phone','relative_2_phone'])validate(id);
 try{checkContacts(data);return true}catch(error){const msg=document.querySelector(`[data-error="${error.field}"]`);if(msg)msg.textContent=error.message;toast(error.message);return false;}
}

let submissionBusy=false,cnhPreparation=null,cnhPrepareTimer=null;
function submissionLoading(show){
 let layer=document.getElementById('submission-loading');
 if(show&&!layer){layer=document.createElement('div');layer.id='submission-loading';layer.className='submission-loading';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','Enviando cadastro');layer.innerHTML='<div class="submission-loading-card" role="status" aria-live="polite"><span class="submission-spinner" aria-hidden="true"></span><strong>Carregando…</strong><p>Aguarde enquanto enviamos seu cadastro.</p></div>';document.body.append(layer);}
 if(!show)layer?.remove();
 const content=document.getElementById('modal-content');if(content)content.inert=show;
 document.getElementById('application-form')?.setAttribute('aria-busy',String(show));
 if(show)document.activeElement?.blur();
}
function cnhSnapshot(){
 const file=$('#cnh')?.files?.[0];if(!ready||!file)return null;
 const full_name=$('#full_name')?.value.trim()||'',cpf=($('#cpf')?.value||'').replace(/\D/g,''),birth=($('#birth_date')?.value||'').split('/');
 if(full_name.split(/\s+/).length<2||!validCpf(cpf)||birth.length!==3||!/^\d{2}\/\d{2}\/\d{4}$/.test($('#birth_date').value)||file.type!=='application/pdf'||file.size>5*1024*1024)return null;
 const birth_date=birth.reverse().join('-'),stamp=JSON.stringify([full_name,cpf,birth_date]);
 return {file,full_name,cpf,birth_date,stamp};
}
function scheduleCnhPreparation(){clearTimeout(cnhPrepareTimer);cnhPrepareTimer=setTimeout(()=>{if(!submissionBusy)prepareCnh();},900);}
function prepareCnh(){
 const snap=cnhSnapshot();if(!snap)return null;
 if(cnhPreparation?.file===snap.file&&cnhPreparation.stamp===snap.stamp&&(!cnhPreparation.receipt||cnhPreparation.receipt.expires>Date.now()+10000))return cnhPreparation;
 const state={...snap,promise:null,receipt:null,error:null};cnhPreparation=state;
 const note=$('#cnh-preparation-note');if(note)note.textContent='Conferindo a CNH enquanto você termina o cadastro…';
 state.promise=(async()=>{try{
  const challenge=await gateway('challenge',{}),proof=await solveProof(challenge),form=new FormData();
  Object.entries({full_name:snap.full_name,cpf:snap.cpf,birth_date:snap.birth_date,challenge_id:challenge.id,challenge_expires:challenge.expires,challenge_signature:challenge.signature,proof}).forEach(([k,v])=>form.append(k,v));
  form.append('cnh',snap.file);const result=await gateway('precheck_cnh',form);state.receipt=result.receipt;
 }catch(error){state.error=error;}
 const current=cnhSnapshot();if(current?.file===snap.file&&current.stamp===snap.stamp&&cnhPreparation===state){const note=$('#cnh-preparation-note');if(note)note.textContent=state.receipt?'CNH conferida. Pronta para enviar.':state.error?.field?state.error.message:'A conferência será concluída ao enviar.';}
 return state;})();return state;
}

async function submitApplication(e){
 e.preventDefault();if(submissionBusy)return;buzz();
 let ok=fields.map(([id])=>validate(id)).every(Boolean);ok=validate('cnh')&&ok;ok=validate('face')&&ok;
 if(!ok){toast('Confira os campos destacados.');return;}
 if(!ready){toast('O envio real depende da conexão com o Supabase.');return;}
 submissionBusy=true;const btn=$('#submit-application');btn.disabled=true;submissionLoading(true);
 try{
  if(!await checkContactFields())return;
  const data=Object.fromEntries(fields.map(([id])=>[id,$('#'+id).value.trim()])),cpf=data.cpf.replace(/\D/g,''),phone=data.phone.replace(/\D/g,'');
  data.birth_date=data.birth_date.split('/').reverse().join('-');
  const snap=cnhSnapshot();
  const preparation=cnhPreparation&&snap?.file===cnhPreparation.file&&snap.stamp===cnhPreparation.stamp&&(!cnhPreparation.receipt||cnhPreparation.receipt.expires>Date.now()+10000)?cnhPreparation:null;
  const challengePromise=gateway('challenge',{}).then(async challenge=>({challenge,proof:await solveProof(challenge)}));
  const [{challenge,proof}]=await Promise.all([challengePromise,preparation?.promise]);
  if(preparation?.error?.field&&preparation.error.field!=='cnh')throw preparation.error;
  const form=new FormData();Object.entries({...data,cpf,phone,motorcycle_id:selectedBike.id,challenge_id:challenge.id,challenge_expires:challenge.expires,challenge_signature:challenge.signature,proof,privacy:'true',requirements:'true'}).forEach(([key,value])=>form.append(key,value));
  const current=cnhSnapshot();
  if(preparation?.receipt&&current?.file===preparation.file&&current.stamp===preparation.stamp)form.append('cnh_receipt',JSON.stringify(preparation.receipt));
  form.append('cnh',$('#cnh').files[0]);form.append('face',$('#face').files[0]);
  const result=await gateway('submit',form);if(!result.id)throw new Error('Confirmação não recebida.');
  clearTimeout(draftTimer);formDrafts.delete(String(selectedBike.id));cnhPreparation=null;
  modal('<h2>CADASTRO ENVIADO COM SUCESSO!</h2><p>Seus dados foram recebidos pela <b>CADASTRO</b>. Aguarde a análise do seu cadastro.</p><button class="btn secondary done-grey" id="done">FECHAR</button>');$('#done').onclick=close;
 }catch(err){
  if(err.field){const msg=document.querySelector('[data-error="'+err.field+'"]');if(msg)msg.textContent=err.message;}
  toast(err.field?err.message:'Não foi possível concluir o envio. '+(err.message||'Tente novamente.'));
 }finally{submissionLoading(false);submissionBusy=false;btn.disabled=false;btn.textContent='ENVIAR CADASTRO';}
}
$('#admin-entry').onclick=async()=>{closeDrawer();if(!ready){modal('<h2>Área administrativa</h2><p>Configure o Supabase no arquivo <b>config.js</b> para ativar o login, os cadastros e a gestão da frota.</p><button class="btn primary" id="gotit">ENTENDI</button>');$('#gotit').onclick=close;return}const {data,error}=await db.auth.getSession();if(error){toast('Erro de autenticação. Tente novamente.');return}if(data.session){session=data.session;close();openAdmin().catch(err=>{console.error(err);toast('Não foi possível abrir a ADM.');})}else login()};
