async function openAdmin(){if(!session)return;navPush('admin');const {data,error}=await db.from('website_admin_users').select('user_id').eq('user_id',session.user.id).maybeSingle();if(error||!data){toast('Este usuário não possui permissão administrativa.');await db.auth.signOut();session=null;return}$('#public').classList.add('hidden');$('header').classList.add('hidden');$('footer')?.classList.add('hidden');$('#admin').classList.remove('hidden');tab='dashboard';await loadAdmin();gateway('housekeeping',{}).catch(()=>{});prepareAdminPush().catch(()=>{});startAdminUpdates()}
$('#admin-public-back').onclick=async()=>{clearDetailUrls();$('#admin').classList.add('hidden');$('#public').classList.remove('hidden');$('header').classList.remove('hidden');$('footer')?.classList.remove('hidden');await loadPublic();window.scrollTo(0,0)};
$('#logout').onclick=async()=>{try{await disableAdminPush()}catch{toast('Não foi possível desativar os avisos. Confira sua conexão e tente sair novamente.');return}clearInterval(adminTimer);await db.auth.signOut();session=null;$('#admin').classList.add('hidden');$('#public').classList.remove('hidden');$('header').classList.remove('hidden');$('footer')?.classList.remove('hidden');await loadPublic();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderAdmin()});
async function loadAdmin(){const [a,n,b,s]=await Promise.all([db.from('website_applications').select('*').order('created_at',{ascending:false}),db.from('website_notifications').select('*').order('created_at',{ascending:false}),db.from('website_motorcycles').select('*').order('sort_order'),db.from('website_site_settings').select('*')]);if([a,n,b,s].some(r=>r.error)){toast('Falha ao atualizar a ADM. Tente novamente.');return}applications=a.data||[];notifications=n.data||[];bikes=b.data||[];settings=Object.fromEntries((s.data||[]).map(x=>[x.key,x.value]));renderAdmin()}
function renderAdmin(){queueMicrotask(()=>{const back=$('#back-admin');if(back)back.onclick=()=>{tab='dashboard';renderAdmin()}});clearDetailUrls();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const root=$('#admin-content');if(tab==='dashboard'){root.innerHTML=`<div class="admin-home"><button id="go-apps" class="admin-home-card"><span class="admin-home-icon">▤</span><strong>CADASTROS</strong><span class="admin-home-arrow">›</span></button><button id="go-bikes" class="admin-home-card"><span class="admin-home-icon">🏍</span><strong>MOTOS</strong><span class="admin-home-arrow">›</span></button><button id="go-notifications" class="admin-home-card"><span class="admin-home-icon">♧</span><strong>NOTIFICAÇÕES</strong><span class="admin-home-arrow">›</span></button></div>`;$('#go-notifications').onclick=()=>{tab='notifications';renderAdmin();enableAdminPush()};$('#go-apps').onclick=()=>{navPush('admin-dashboard');tab='applications';renderAdmin()};$('#go-bikes').onclick=()=>{navPush('admin-dashboard');tab='motorcycles';renderAdmin()};}else if(tab==='applications'){root.innerHTML=`<button class="mini admin-back" id="back-admin">← Voltar</button><div class="panel"><h2>Cadastros</h2><div class="toolbar"><input id="app-search" class="search" placeholder="Pesquisar nome ou CPF"><select id="app-filter" class="search"><option value="">Todos os status</option><option>Pendente</option><option>Aprovado</option><option>Recusado</option><option value="trash">Lixeira</option></select></div><div id="app-list"></div></div>`;$('#app-search').oninput=renderAppList;$('#app-filter').onchange=renderAppList;renderAppList()}else if(tab==='motorcycles'){root.innerHTML=`<button class="mini admin-back" id="back-admin">← Voltar</button><div class="panel"><div class="itemhead"><h2>Motos</h2><button id="add-bike" class="btn primary">+ Adicionar moto</button></div><div id="bike-admin-list"></div></div>`;$('#add-bike').onclick=()=>editBike();renderBikeAdmin()}else if(tab==='notifications'){root.innerHTML=`<button class="mini admin-back" id="back-admin">← Voltar</button><div class="panel"><h2>Notificações no celular</h2><p>Receba um aviso quando um cliente concluir um novo cadastro, mesmo com o site fechado ou a tela bloqueada.</p><p id="push-status" class="muted" role="status">Verificando este aparelho...</p><div class="actions"><button id="enable-push" class="btn primary">ATIVAR NOTIFICAÇÕES</button><button id="test-push" class="btn secondary">ENVIAR TESTE NESTE APARELHO</button><button id="disable-push" class="mini">DESATIVAR NESTE APARELHO</button></div><p class="muted">No iPhone: abra no Safari, toque em Compartilhar → Adicionar à Tela de Início e abra pelo ícone Cadastro. Depois entre na ADM e ative aqui. Permita também os avisos na Tela Bloqueada nos Ajustes do aparelho. O modo Foco e as configurações do sistema podem silenciar os avisos. Ao sair da ADM, os avisos serão desativados neste aparelho.</p></div><div class="panel"><h2>Avisos de cadastros</h2><div class="toolbar"><select id="notif-filter" class="search"><option value="all">Todas</option><option value="unread">Não lidas</option><option value="read">Lidas</option></select><input id="notif-search" class="search" placeholder="Pesquisar cliente"></div><div id="notif-list"></div></div>`;$('#enable-push').onclick=enableAdminPush;$('#disable-push').onclick=()=>disableAdminPush().catch(e=>toast(e.message));$('#test-push').onclick=testAdminPush;pushStatus();$('#notif-filter').onchange=renderNotifs;$('#notif-search').oninput=renderNotifs;renderNotifs()}else{root.innerHTML=`<div class="panel"><h2>Configurações</h2><div class="field"><label>WhatsApp da empresa (DDD + número)</label><input id="setting-phone" value="${esc(settings.whatsapp||'')}" placeholder="95999999999"></div><button class="btn primary" id="save-settings">SALVAR</button></div>`;$('#save-settings').onclick=async()=>{let value=$('#setting-phone').value.replace(/\D/g,'');if(value&&!/^\d{10,11}$/.test(value)){toast('Informe DDD e número, sem o código 55.');return}const {error}=await db.from('website_site_settings').upsert({key:'whatsapp',value});if(error)toast(error.message);else{toast('Configuração salva.');settings.whatsapp=value}}}}
